theme.css:
/* theme: Broken Circuit | A day of cracked foundations—trust and markets both shorting out, with defensive green the only steady signal. */

.diary-page {
  --paper: #f2f4ef;
  --paper-alt: #e8ece4;
  --ink: #1d231b;
  --ink-soft: #3d463a;
  --muted: #5a6453;
  --accent: #b83227;
  --accent-ink: #ffffff;
  --rule: #cbd3c4;
  --font-display: var(--ff-space-grotesk), sans-serif;
  --font-body: var(--ff-newsreader), serif;
  --font-ui: var(--ff-inter), sans-serif;
}

@media (prefers-color-scheme: dark) {
  .diary-page {
    --paper: #151713;
    --paper-alt: #1d201b;
    --ink: #e8ede3;
    --ink-soft: #c5cdbf;
    --muted: #9aa696;
    --accent: #ff6b5e;
    --accent-ink: #1a0d0a;
    --rule: #333b30;
  }
}

.diary-page .diary-hero {
  background: var(--paper-alt);
  border-bottom: 1px solid var(--rule);
  position: relative;
  overflow: hidden;
}

.diary-page .diary-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, transparent 49.5%, var(--accent) 49.5%, var(--accent) 50.5%, transparent 50.5%),
    linear-gradient(0deg, transparent 49.5%, var(--accent) 49.5%, var(--accent) 50.5%, transparent 50.5%);
  background-size: 60px 60px;
  opacity: 0.05;
  pointer-events: none;
}

.diary-page .diary-hero-inner {
  position: relative;
}

.diary-page .diary-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.diary-page .diary-kicker::before {
  content: "▼";
  font-size: 0.55em;
  color: var(--accent);
}

.diary-page .diary-title {
  position: relative;
  padding-bottom: 0.4em;
}

.diary-page .diary-title::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 4px;
  background: repeating-linear-gradient(90deg, var(--accent) 0 12px, transparent 12px 18px);
}

.diary-page .diary-summary {
  max-width: 48rem;
}

.diary-page .diary-theme-note {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  letter-spacing: 0.04em;
}

.diary-page .diary-toc {
  border-bottom: 1px solid var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    border-bottom: 0;
  }
}

.diary-page .diary-toc-link.is-active {
  border-left-color: var(--accent);
  color: var(--accent);
  font-weight: 600;
}

.diary-page .diary-toc-number {
  font-family: var(--font-ui);
  letter-spacing: 0.12em;
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
}

.diary-page .diary-section-head {
  border-bottom: 2px solid var(--accent);
  padding-bottom: 0.6rem;
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.18em;
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-weight: 600;
  letter-spacing: -0.02em;
}

.diary-page .diary-prose {
  font-family: var(--font-body);
  line-height: 1.8;
}

.diary-page .diary-prose h3 {
  font-family: var(--font-display);
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  position: relative;
  padding-bottom: 0.35rem;
  border-bottom: 1px dashed var(--rule);
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  font-weight: 500;
}

.diary-page .diary-prose strong {
  font-weight: 650;
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  content: "";
  width: 0.5rem;
  height: 2px;
  background: var(--accent);
  border-radius: 2px;
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  border-left-width: 2px;
  font-style: normal;
  padding-left: 1.5rem;
  color: var(--ink);
  position: relative;
}

.diary-page .diary-prose blockquote::before {
  content: "”";
  position: absolute;
  left: 0.2rem;
  top: -0.4em;
  font-family: var(--font-display);
  font-size: 2.2em;
  color: var(--accent);
  opacity: 0.3;
}

.diary-page .diary-prose hr {
  border-top: 1px dashed var(--rule);
}

.diary-page .diary-prose code {
  color: var(--accent);
}

.diary-page .diary-prose pre {
  border-left: 3px solid var(--accent);
  padding-left: 1.2rem;
}

.diary-page .diary-section:first-child .diary-prose > p:first-of-type::first-letter {
  font-family: var(--font-display);
  color: var(--accent);
  font-weight: 600;
}

.diary-page .diary-footer {
  border-top: 1px solid var(--accent);
  position: relative;
}

.diary-page .diary-footer::before {
  content: "";
  position: absolute;
  top: -1px;
  left: 0;
  width: 100%;
  height: 1px;
  background: repeating-linear-gradient(90deg, var(--accent) 0 8px, transparent 8px 14px);
}

.diary-page .diary-footer a {
  font-family: var(--font-ui);
  font-weight: 500;
  text-decoration: none;
  border-bottom: 1px solid var(--accent);
  padding-bottom: 0.1em;
  transition: color 150ms, border-color 150ms;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
  border-color: var(--accent);
}

@media (max-width: 1023px) {
  .diary-page .diary-toc {
    background: var(--paper);
    scrollbar-width: none;
  }

  .diary-page .diary-toc-list {
    gap: 0.75rem;
  }

  .diary-page .diary-toc-link {
    padding: 0.3rem 0.7rem;
    border: 1px solid var(--rule);
    border-radius: 2px;
    color: var(--muted);
  }

  .diary-page .diary-toc-link.is-active {
    background: var(--accent);
    color: var(--accent-ink);
    border-color: var(--accent);
  }

  .diary-page .diary-toc-link.is-active .diary-toc-number {
    color: var(--accent-ink);
  }
}
